const isElementInViewport = (element) => {
    const rect = element.getBoundingClientRect();
    return (
        rect.top >= 0 &&
        rect.left >= 0 &&
        rect.bottom <= (window.innerHeight || document.documentElement.clientHeight) &&
        rect.right <= (window.innerWidth || document.documentElement.clientWidth)
    );
};

if (isElementInViewport(bookmarkElement)) {
    showPopupover();
} else {
    // Optionally, you can set up an Intersection Observer if needed
    const initialObserver = new IntersectionObserver((entries) => {
        entries.forEach((entry) => {
            if (entry.isIntersecting) {
                showPopupover();
                initialObserver.unobserve(entry.target);
            }
        });
    });
    initialObserver.observe(bookmarkElement);
}
